"""Debates (sétima leva): preconceitos chamados de fobias, psicopatia, outras condições que causam dano, plágio e pirataria."""
SEP = 'https://plato.stanford.edu/entries/'
WE = 'https://en.wikipedia.org/wiki/'
LD, CO = 'Liberdade e dano', 'Cotidiano'

DEBATES7 = [
dict(s='fobias-e-preconceitos', n='Homofobia, transfobia, xenofobia: “fobias” que prejudicam', t=LD, r='O nome diz medo, mas o que elas produzem é dano a outros. São condições, atitudes ou escolhas? E o que isso muda na responsabilidade?',
 v='Homofobia, transfobia, xenofobia, gordofobia: o sufixo sugere uma fobia clínica, como medo de altura. Mas, diferente das fobias, elas não ficam dentro de quem as tem: viram piada, exclusão, lei e violência contra pessoas concretas. A pergunta ética é dupla: como elas prejudicam, e quem responde por elas.',
 lados=[('Como prejudicam', ['Violência direta: pessoas LGBT e imigrantes sofrem agressões em taxas muito mais altas; o Brasil está entre os países que mais matam pessoas trans.', 'Dano psicológico mensurável: rejeição familiar e social multiplica o risco de depressão e suicídio entre jovens LGBT; o “estresse de minoria” tem efeito documentado sobre a saúde.', 'Exclusão: emprego, moradia, escola e serviços negados ou hostis, com custo econômico e de vida.', 'Leis e políticas: criminalização, negação de direitos e de cuidado, feitas em nome de um “medo” que recai sobre quem é temido.', 'Efeito sobre todos: normas de masculinidade rígida, medo do diferente e policiamento mútuo empobrecem a vida também de quem discrimina.']),
        ('Condição, atitude ou escolha?', ['Não são fobias no sentido clínico: não há evitação ansiosa; há hostilidade, repulsa e crença na inferioridade do outro. O nome é uma metáfora, e pode servir de desculpa (“não controlo meu medo”).', 'Têm raízes psicológicas reais: nojo, medo do que ameaça a identidade do grupo, insegurança sobre a própria masculinidade (há estudos ligando homofobia a atração reprimida em parte dos casos).', 'Mas a origem de uma atitude não a justifica, nem exime: todo preconceito tem raiz psicológica, e a responsabilidade começa quando ele vira ato.', 'São aprendidas e podem ser desaprendidas: convivência e informação reduzem o preconceito de forma consistente nos estudos.'])],
 c=['Distinguir desconforto privado (que a pessoa pode trabalhar) de hostilidade pública (que prejudica outros): a ética julga o segundo.', 'Chamar de “fobia” ajuda a nomear e atrapalha a responsabilizar; alguns preferem “preconceito” ou “discriminação”.', 'Quem foi criado nelas não escolheu começar com elas; escolhe o que faz quando confrontado com a evidência e com as pessoas.'],
 p=('forte', 'Não há debate sobre o dano: ele é documentado, grave e recai sobre quem não fez nada a ninguém. Sobre a natureza, a convergência é que não se trata de fobias clínicas, e sim de preconceitos aprendidos com base psicológica, o que os torna tratáveis e não os desculpa. A responsabilidade não é por sentir, e sim pelo que se faz com o sentimento: agir, calar ou mudar. Veja as fronteiras da parcialidade na seção de critérios.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo', 'Dano enorme, sem benefício a ninguém; a atitude é errada pelas consequências.'), ('deontologia-kantiana', 'Kant', 'Tratar alguém como inferior por um traço é negar-lhe a dignidade.'), ('sencientismo', 'Sencientismo', 'O sofrimento de quem é alvo conta igual; o traço do alvo é irrelevante.'), ('etica-das-virtudes', 'Virtudes', 'O preconceito é um vício de percepção; a hospitalidade e a justiça, virtudes a cultivar.'), ('etica-do-cuidado', 'Cuidado', 'Pergunta quem é ferido e o que precisa; a resposta é proteção e pertencimento.')],
 licoes=['tribalismo-moral', 'emocoes-morais', 'vieses-morais', 'imparcialidade'],
 fx=[('Minority stress (Wikipédia)', WE + 'Minority_stress'), ('Homophobia (Wikipédia)', WE + 'Homophobia'), ('Discrimination (Stanford Encyclopedia)', SEP + 'discrimination/')]),

dict(s='psicopatia', n='Psicopatia e responsabilidade', t=LD, r='Pessoas com psicopatia entendem as regras e não sentem o que elas protegem. São responsáveis pelo que fazem? E o que a sociedade deve a elas e às suas vítimas?',
 v='Psicopatia (ou transtorno de personalidade antissocial em sua forma grave) combina ausência de empatia e remorso, manipulação, impulsividade e frieza. Afeta cerca de 1% da população e uma parcela muito maior da população carcerária. Ela coloca um problema real para a ética: se a pessoa sabe o que é errado mas não sente nenhuma razão para não fazer, ela é responsável?',
 lados=[('Como prejudica', ['Violência, fraude e manipulação com frequência e frieza muito acima da média; vítimas que não são reconhecidas como vítimas por quem as feriu.', 'Em posições de poder, o dano se multiplica: a tétrade sombria (narcisismo, maquiavelismo, psicopatia, sadismo) aparece entre os responsáveis pelas piores atrocidades da história.', 'Custo para famílias e relações: o dano começa em casa e é invisível de fora.']),
        ('É responsável?', ['Sim, dizem a maioria dos juristas e parte dos filósofos: a pessoa entende a diferença entre certo e errado (o teste legal), controla seus atos e escolhe. A falta de empatia não é falta de capacidade de saber.', 'Em parte, dizem outros (Fine e Kennett, Neil Levy): se o conhecimento moral exige entender por que algo é errado, e não só que é proibido, a pessoa com psicopatia tem um déficit real; estudos mostram que ela distingue mal regras morais de convenções.', 'Não escolheu ter a condição: há base genética e de desenvolvimento, inclusive maus-tratos na infância. Isso não exime do ato, mas pesa sobre a punição e sobre a prevenção.'])],
 c=['Responsabilidade é uma escala: a condição reduz a capacidade de responder às razões morais sem anulá-la, e o direito já faz distinções desse tipo.', 'Separar a pergunta sobre culpa da pergunta sobre o que fazer: mesmo que a culpa seja reduzida, a proteção das vítimas é devida, e a punição pode ser justificada pela prevenção.', 'Tratamento: a evidência de que a psicopatia adulta responde a tratamento é fraca; intervenções precoces em crianças com traços de insensibilidade têm resultados melhores.', 'O rótulo é usado de forma solta para qualquer pessoa má; o termo clínico é mais estreito, e a maioria das pessoas que causa dano não o tem.', 'Psicólogos morais descrevem a postura como um solipsismo moral de fato: os outros não são registrados como sujeitos com reivindicações próprias. É uma descrição de déficit, não uma teoria que alguém defenda, e difere do egoísmo ético, que é uma tese argumentada.'],
 p=('parcial', 'Sobre o dano, não há debate. Sobre a responsabilidade, o peso está com uma posição intermediária: a pessoa com psicopatia é responsável porque entende e controla, mas sua capacidade de responder a razões morais é reduzida, o que deve pesar na punição e, sobretudo, na prevenção. O que a sociedade deve às vítimas é proteção; o que deve a quem tem a condição é tratamento quando possível e punição proporcional, não vingança. Veja a lição sobre livre-arbítrio.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo', 'Responsabilizar e conter pela prevenção e proteção; a culpa metafísica importa menos do que o que funciona.'), ('deontologia-kantiana', 'Kant', 'Responsabilidade exige agência racional, que a pessoa tem; a falta de sentimento não anula o dever.'), ('etica-do-cuidado', 'Cuidado', 'Atenção às vítimas primeiro; e prevenção na infância, onde o cuidado ainda muda trajetórias.'), ('etica-das-virtudes', 'Virtudes', 'A psicopatia é a ausência das virtudes de sentimento; o que resta é a capacidade de seguir regras, que se exige.')],
 licoes=['livre-arbitrio-e-responsabilidade', 'emocoes-morais', 'situacionismo-e-experimentos'],
 fx=[('Psychopathy (Wikipédia)', WE + 'Psychopathy'), ('Moral Responsibility and Psychopathy (Stanford Encyclopedia: Moral Responsibility)', SEP + 'moral-responsibility/'), ('Atores malevolentes (Política Para Iniciantes)', 'https://politicaparainiciantes.biblioverse.org/atores-malevolentes.html')]),

dict(s='condicoes-que-causam-dano', n='Condições que causam dano: dependência, transtornos, abuso', t=LD, r='Algumas condições tornam provável o dano a outros. A ética separa a condição do ato, a pessoa do risco, e pergunta o que previne.',
 v='Dependência química, transtornos de personalidade, transtornos do controle de impulsos, pedofilia: condições que a pessoa não escolheu e que aumentam a chance de prejudicar alguém. A ética precisa fazer três coisas ao mesmo tempo: dizer com clareza como o dano acontece, não confundir ter a condição com agir, e perguntar o que de fato protege as vítimas.',
 lados=[('Como cada uma prejudica', ['Dependência química: o dano vai de acidentes e violência sob efeito a negligência de filhos e roubo para sustentar o uso; a maior parte recai sobre a família.', 'Transtornos de personalidade graves (antissocial, narcisista, borderline em alguns casos): manipulação, abuso emocional, instabilidade que fere quem está perto; o dano é relacional e muitas vezes invisível.', 'Transtornos do controle de impulsos: explosões de violência, jogo compulsivo que arruína a família.', 'Pedofilia (a atração, não o ato): quando leva ao ato, o dano a crianças é dos mais graves que existem, duradouro e muitas vezes irreparável. Esse é o fato central, e nada nesta página o relativiza.']),
        ('Condição e ato: o que a ética separa', ['Ter uma condição não é um ato, e não é escolhido; agir é. A responsabilidade começa no ato, e a prevenção começa antes dele.', 'Pessoas com pedofilia que nunca cometeram abuso existem e buscam ajuda; programas de prevenção (como o Dunkelfeld, na Alemanha) tratam a atração antes que vire ato, e protegem crianças. Tratar a condição como crime em si empurra essas pessoas para longe do tratamento e aumenta o risco.', 'Dependência é hoje entendida como doença com componente de escolha; tratar como crime piora os resultados, e tratar como saúde os melhora. Isso não exime do dano causado sob efeito.', 'A pessoa com um transtorno é responsável pelo que faz com ele: buscar tratamento, evitar situações de risco, reparar. A condição explica; não desculpa.'])],
 c=['A proteção das vítimas, sobretudo crianças, vem antes de qualquer consideração sobre quem tem a condição; as duas coisas não competem, porque prevenir é proteger.', 'A reação social à pedofilia é tão intensa que confunde quem sente com quem age, e isso tem um custo em crianças abusadas por quem não procurou ajuda.', 'A responsabilidade é uma escala: capacidade reduzida de controle pesa na culpa e na pena, não na proteção devida.'],
 p=('parcial', 'Sobre o dano, não há debate, e ele deve ser dito sem eufemismo: o abuso de crianças, a violência sob efeito e o abuso relacional ferem pessoas concretas. Sobre como responder, o peso está com a distinção entre condição e ato: a condição pede tratamento e prevenção; o ato pede responsabilidade, proteção das vítimas e punição proporcional. A evidência mostra que essa separação protege mais do que a punição da condição em si.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo', 'O que reduz o dano total é prevenção e tratamento antes do ato, e proteção e contenção depois.'), ('deontologia-de-direitos', 'Direitos', 'O direito das vítimas, sobretudo crianças, a não ser feridas é absoluto; o direito de quem tem a condição é a tratamento e a não ser punido pelo que não fez.'), ('etica-do-cuidado', 'Cuidado', 'Atenção às vítimas e às pessoas em risco de causar dano, porque as duas atenções previnem.'), ('etica-das-virtudes', 'Virtudes', 'A pessoa com uma condição de risco que busca ajuda e evita o dano exerce a virtude que a situação permite.'), ('deontologia-kantiana', 'Kant', 'Responsabilidade proporcional à agência; dever de buscar os meios de não ferir.')],
 licoes=['livre-arbitrio-e-responsabilidade', 'fraqueza-de-vontade', 'bioetica'],
 fx=[('Prevention Project Dunkelfeld (Wikipédia)', WE + 'Prevention_Project_Dunkelfeld'), ('Addiction (Wikipédia)', WE + 'Addiction'), ('Moral Responsibility (Stanford Encyclopedia)', SEP + 'moral-responsibility/'), ('Child sexual abuse (Wikipédia)', WE + 'Child_sexual_abuse')]),

dict(s='plagio', n='Plágio', t=CO, r='Apresentar como seu o que é de outro: quem é prejudicado, por que é diferente de copiar, e onde a inteligência artificial muda a pergunta.',
 v='Plágio é usar ideias, textos ou obras de outra pessoa sem atribuição, apresentando-os como próprios. Parece crime sem vítima: ninguém perde o texto original. A ética mostra que há vítimas, e explica o que é devido a quem criou.',
 lados=[('Por que é errado', ['Engano: o plágio mente sobre a autoria a quem lê, avalia ou compra; é uma forma de fraude, e a vítima primeira é quem foi enganado.', 'Apropriação: o crédito é parte do que um autor recebe pelo trabalho; tirá-lo é tirar algo real, mesmo sem tirar o texto.', 'Injustiça com os outros: na escola e na ciência, quem plagia obtém o que outros obtiveram com esforço, e distorce a avaliação de todos.', 'Corrosão da confiança: ciência, jornalismo e ensino dependem de que a autoria seja verdadeira; cada fraude gasta um pouco disso.']),
        ('O que não é plágio, e as zonas cinzentas', ['Citar com atribuição, parafrasear com crédito e usar ideias comuns não é plágio.', 'Autoplágio (reapresentar o próprio trabalho como novo) engana sobre novidade, não sobre autoria; é falha menor, mas é falha.', 'Inteligência artificial: usar um texto gerado por máquina não rouba de um autor específico, mas engana sobre a autoria e sobre o esforço; a regra que sobrevive é transparência sobre o que a ferramenta fez.', 'Em culturas e épocas com outra noção de autoria (imitação como homenagem), o conceito muda; o que não muda é o erro de enganar quem avalia.'])],
 c=['A gravidade varia: colar numa prova prejudica colegas; plagiar uma pesquisa pode prejudicar o conhecimento e as vidas que dependem dele.', 'Plágio e violação de direitos autorais são coisas diferentes: pode-se plagiar uma obra em domínio público, e pode-se violar direitos citando a autoria.', 'A pressão por produtividade na academia é causa real de plágio, e vale ser tratada; não desculpa o ato.'],
 p=('forte', 'Há consenso: o plágio é errado porque engana sobre a autoria e se apropria do crédito que é parte do trabalho de outro, prejudicando quem criou, quem avalia e quem compete honestamente. As zonas cinzentas (autoplágio, uso de inteligência artificial) se resolvem pelo mesmo critério: dizer a verdade sobre quem fez o quê.'),
 teorias=[('deontologia-kantiana', 'Kant', 'Mentir sobre a autoria trata o leitor e o autor como meios; a máxima não é universalizável.'), ('utilitarismo-classico', 'Utilitarismo', 'Destrói a confiança de que ciência e ensino dependem; o dano é difuso e real.'), ('etica-das-virtudes', 'Virtudes', 'Honestidade intelectual e justiça com quem criou.'), ('consequencialismo-de-regras', 'Consequencialismo de regras', 'A regra “atribua sempre” produz um sistema de conhecimento que funciona.')],
 licoes=['etica-da-crenca', 'etica-da-tecnologia', 'dilemas-do-cotidiano'],
 fx=[('Plagiarism (Wikipédia)', WE + 'Plagiarism'), ('Scientific misconduct (Wikipédia)', WE + 'Scientific_misconduct'), ('Research integrity (Wikipédia)', WE + 'Research_integrity'), ('Plágio (Wikipédia)', 'https://pt.wikipedia.org/wiki/Pl%C3%A1gio')]),

dict(s='pirataria', n='Pirataria', t=CO, r='Baixar um filme, um livro ou um programa sem pagar: roubo, carona ou acesso legítimo? Depende de quem perde o quê.',
 v='Copiar sem autorização uma obra protegida não tira nada do dono: ele continua com a obra. Isso a torna diferente do roubo, e é o que faz o debate existir. A pergunta é se alguém perde algo, o quê, e se há casos em que a cópia é defensável.',
 lados=[('Por que é errado, em geral', ['Carona: quem copia usa o que foi criado com o pagamento dos outros; se todos copiassem, não haveria o que copiar. A máxima não é universalizável.', 'Perda real, embora indireta: cada cópia que substitui uma compra é renda que não chegou a quem criou; autores e artistas menores sentem isso mais do que grandes empresas.', 'Promessa implícita: o acesso legal vem com um termo; violá-lo é quebrar um acordo que se aceitou ao entrar.', 'Hábito: a exceção que parece inofensiva forma a pessoa que se dá exceções.']),
        ('Quando a defesa é mais forte', ['Sem alternativa legal: obra fora de catálogo, não lançada no país ou sem versão acessível. Ninguém perde uma venda que não existia.', 'Quem não poderia pagar: uma cópia por quem jamais compraria não substitui venda; o dano é zero e o benefício, real. O argumento vale para o pobre, não para quem prefere não pagar.', 'Preservação e acesso ao conhecimento: bibliotecas-sombra e arquivos mantêm obras que a indústria deixa morrer; o acesso à ciência financiada por dinheiro público é um caso à parte, com argumentos fortes a favor.', 'Direitos autorais excessivos: prazos de décadas após a morte do autor servem a empresas, não a criadores; a crítica ao sistema não autoriza a cópia, mas enfraquece a condenação.'])],
 c=['Pirataria não é roubo nem é inofensiva: é carona, e a ética da carona depende de quem mais está pagando.', 'A evidência sobre efeito nas vendas é mista: parte da cópia substitui compra, parte gera demanda; varia por mídia e por preço.', 'Grandes plataformas e pequenos criadores estão em posições opostas, e o mesmo ato os afeta de forma diferente.'],
 p=('parcial', 'O peso está contra a pirataria como hábito: o argumento da carona e da universalização a condena quando há alternativa legal acessível e quem copia poderia pagar. As exceções defensáveis existem e são claras: obra sem acesso legal, pessoa que não poderia pagar, preservação e acesso ao conhecimento financiado publicamente. O teste honesto é o de sempre: você diria o seu motivo em público, e ele vale para todos?'),
 teorias=[('deontologia-kantiana', 'Kant', '“Copio sem pagar” não é universalizável; a prática depende dos que pagam.'), ('utilitarismo-classico', 'Utilitarismo', 'Depende: cópia que substitui venda prejudica; cópia sem venda possível só beneficia. A conta é caso a caso e o hábito pesa.'), ('deontologia-de-direitos', 'Direitos', 'Propriedade intelectual como direito do criador, com a ressalva de que seus limites atuais são contestados.'), ('consequencialismo-de-regras', 'Consequencialismo de regras', 'Regras que pagam criadores e garantem acesso produzem mais bem do que a cópia livre ou a proibição total.'), ('etica-das-virtudes', 'Virtudes', 'Integridade: pagar pelo que se usa quando se pode; generosidade com o conhecimento quando o sistema falha.')],
 licoes=['kant-e-o-imperativo-categorico', 'dilemas-do-cotidiano', 'fazer-e-deixar-acontecer'],
 fx=[('Intellectual Property (Stanford Encyclopedia)', SEP + 'intellectual-property/'), ('Copyright infringement (Wikipédia)', WE + 'Copyright_infringement'), ('Free-rider problem (Wikipédia)', WE + 'Free-rider_problem')]),
]
assert len({d['s'] for d in DEBATES7}) == len(DEBATES7)
